// 레벨업과외 — Cloudflare Worker
// 요청마다 페이지를 동적으로 생성·서빙하고, 상담 신청(/api/inquiry)을 처리합니다.
// 배포:  npx wrangler deploy   (자세한 내용은 README.md / wrangler.toml 참고)

// 상담 신청 시 이메일 알림 발송용 (Cloudflare Email Routing)
import { EmailMessage } from "cloudflare:email";
import { tryRenderSeoPage, seoSitemapPaths, seoCoreSitemapPaths, seoLongTailPaths, seoLastmod, DEPLOY_DATE } from "./seo_pages.js";
import { PAGES, PAGE_PATHS } from "./site_pages.js";

// IndexNow 키 (네이버·빙 자동 색인 제출용). 이 값은 /키.txt 로도 응답해야 합니다.
const INDEXNOW_KEY = "7c3f9a2e5b8d416cbf0e93b7d5a2c81f";

// 페이지 HTML은 site_pages.js (src/pages/*.html 에서 build_pages.mjs 로 생성) 에서 가져온다.
// 우클릭·복사·개발자도구 방지 스크립트. 모든 페이지 끝에 붙는다.
const ANTICOPY = `<script>(function(){var ok=function(e){var t=e.target;return t&&/^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName);};document.addEventListener('contextmenu',function(e){if(!ok(e))e.preventDefault();});document.addEventListener('dragstart',function(e){if(!ok(e))e.preventDefault();});document.addEventListener('copy',function(e){if(!ok(e))e.preventDefault();});document.addEventListener('keydown',function(e){var k=(e.key||'').toLowerCase();if(e.key==='F12'){e.preventDefault();return;}if(e.ctrlKey&&e.shiftKey&&['i','j','c'].indexOf(k)>-1){e.preventDefault();return;}if(e.ctrlKey&&!ok(e)&&['u','s'].indexOf(k)>-1){e.preventDefault();return;}});})();</script>`;
function renderSitePage(path, env) {
  const page = PAGES[path];
  if (!page) return null;
  const year = new Date().getFullYear();
  const verify = [
    env.GOOGLE_SITE_VERIFICATION ? '<meta name="google-site-verification" content="' + env.GOOGLE_SITE_VERIFICATION + '" />' : '',
    '<meta name="naver-site-verification" content="273ef2347501449d16495e2308567e31fd2d43cb" />',
    env.BING_SITE_VERIFICATION ? '<meta name="msvalidate.01" content="' + env.BING_SITE_VERIFICATION + '" />' : '',
  ].filter(Boolean).join("\n");
  return page.html.replaceAll("{{YEAR}}", String(year)).replace("{{VERIFY}}", verify).replace("{{ANTICOPY}}", ANTICOPY);
}

const FAVICON_ICO = "";
const APPLE_ICON = "";

function b64ToBytes(b64) {
  const bin = atob(b64);
  const arr = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i);
  return arr;
}

function json(data, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { "content-type": "application/json; charset=utf-8" },
  });
}

async function handleInquiry(request, env) {
  let data;
  try { data = await request.json(); }
  catch { return json({ ok: false, error: "요청 형식이 올바르지 않습니다." }, 400); }

  const name = (data.name || "").toString().trim();
  const phone = (data.phone || "").toString().trim();
  const address = (data.address || "").toString().trim();
  // 주소는 홈 상담 폼에서만 받는다. 하위 페이지의 간단 폼(이름·연락처·내용)은 주소 없이 접수한다.
  if (!name || !phone) {
    return json({ ok: false, error: "학생 이름과 학부모 연락처를 입력해주세요." }, 400);
  }

  const atDisplay = new Date().toLocaleString("ko-KR", {
    timeZone: "Asia/Seoul",
    year: "numeric", month: "long", day: "numeric",
    hour: "2-digit", minute: "2-digit", hour12: true,
  });

  // 사람에게 보이지 않는 칸이 채워져 있으면 봇이다. 접수한 척하고 버린다.
  if (String(data.hp || "").trim()) return json({ ok: true });

  const record = {
    site: env.SITE_NAME || "레벨업과외",
    name,
    phone,
    address,
    grade: (data.grade || "").toString(),
    subjects: Array.isArray(data.subjects) ? data.subjects : [],
    message: (data.message || "").toString().trim(),
    // 어느 페이지에서 온 문의인지. 어떤 유형의 페이지가 실제로 문의를
    // 만드는지 알아야 페이지 전략을 데이터로 판단할 수 있다.
    page: (data.page || "").toString().slice(0, 200),
    at: new Date().toISOString(),
    atDisplay,
  };

  // 상담 신청은 이 사이트의 유일한 전환 지점이다.
  // 이전에는 메일·시트가 모두 실패해도 ok:true 를 돌려줘서, 학부모에게는
  // "신청 완료"가 뜨고 신청은 아무 데도 남지 않았다. 한 곳이라도 기록에
  // 성공했을 때만 성공으로 응답한다.
  let mailOk = false, sheetOk = false;
  let lastError = "";

  // ───────── 1) 이메일 알림 발송 (Cloudflare Email Routing) ─────────
  try {
    // 대시보드 변수가 비어도 동작하도록 기본 수신 주소를 둔다.
    // 설정 하나가 빠졌다고 문의가 통째로 사라지면 안 된다.
    const NOTIFY_TO_DEFAULT = "hhhyunee3@naver.com";
    if (env.NOTIFY) {
      const to = env.NOTIFY_TO || NOTIFY_TO_DEFAULT;
      const from = env.NOTIFY_FROM || "noreply@level-up-lesson.com";
      const subjLabel = record.subjects.length ? record.subjects.join("·") + " " : "";
      const subject = "[레벨업과외] " + subjLabel + "상담 신청 - " + name;
      const raw = buildMime({ from, fromName: "레벨업과외", to, subject, html: renderEmailHtml(record) });
      // 런타임에 따라 EmailMessage 생성자 대신 객체 형태만 받는 경우가 있다.
      // 한쪽이 막히면 다른 쪽으로 한 번 더 시도한다.
      try {
        await env.NOTIFY.send(new EmailMessage(from, to, raw));
      } catch (e1) {
        console.log("EmailMessage 방식 실패, 객체 방식 재시도:", e1 && e1.message ? e1.message : e1);
        await env.NOTIFY.send({ from, to, raw });
      }
      mailOk = true;
      console.log("상담 알림 메일 발송 성공 →", to);
    } else {
      lastError = "NOTIFY 바인딩 없음 (wrangler.toml 의 [[send_email]] 확인)";
      console.log("상담 알림 메일 건너뜀 -", lastError);
    }
  } catch (e) {
    lastError = e && e.message ? e.message : String(e);
    console.log("상담 알림 메일 발송 실패:", lastError);
  }

  // ───────── 2) 구글 시트 기록 (Apps Script 웹앱) ─────────
  try {
    if (env.SHEET_WEBHOOK_URL) {
      const r = await fetch(env.SHEET_WEBHOOK_URL, {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify(record),
      });
      sheetOk = r.ok;
      if (!r.ok) console.log("구글 시트 기록 실패: HTTP", r.status);
    }
  } catch (e) {
    console.log("구글 시트 기록 실패:", e && e.message ? e.message : e);
  }

  console.log("새 상담 신청:", JSON.stringify(record), "| 메일:", mailOk, "| 시트:", sheetOk);

  if (!mailOk && !sheetOk) {
    // 어디에도 남지 않았다. 완료라고 말하면 신청이 그대로 사라진다.
    console.log("상담 신청 저장 실패 — 사유:", lastError);
    return json({
      ok: false,
      error: "접수 중 문제가 발생했습니다. 번거로우시겠지만 010-3038-8978 로 전화 주시면 바로 도와드리겠습니다.",
    }, 500);
  }
  return json({ ok: true });
}

// UTF-8 문자열을 RFC 2047 인코딩 워드(=?UTF-8?B?...?=)로 변환 — 한글 제목/이름용
function encodeWord(s) {
  const b64 = btoa(String.fromCharCode(...new TextEncoder().encode(s)));
  return "=?UTF-8?B?" + b64 + "?=";
}

// 사용자 입력을 HTML에 안전하게 넣기 위한 이스케이프
function escapeHtml(s) {
  return String(s == null ? "" : s)
    .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

// 상담 신청 알림 메일 본문(HTML 카드) 생성
function renderEmailHtml(r) {
  const tel = String(r.phone).replace(/[^0-9+]/g, "");
  const subjects = r.subjects.length ? r.subjects.join(", ") : "-";
  const grade = r.grade || "-";
  const message = r.message ? escapeHtml(r.message).replace(/\n/g, "<br>") : "-";
  const sky = "#15A3E6", ink = "#0E3550", line = "#EAEFF3", soft = "#EAF7FE";

  const cell = "padding:14px 0;font-size:14px;color:#7C8A99;width:104px;vertical-align:top;";
  const val = "padding:14px 0;font-size:15px;font-weight:700;color:" + ink + ";border-bottom:1px solid " + line + ";";
  let rows = [
    ["학생 이름", escapeHtml(r.name)],
    ["학년", escapeHtml(grade)],
    ["희망 과목", escapeHtml(subjects)],
  ].map(function (kv) {
    return '<tr><td style="' + cell + '">' + kv[0] + '</td><td style="' + val + '">' + kv[1] + '</td></tr>';
  }).join("");

  rows += '<tr><td style="' + cell + '">📞 학부모 연락처</td>' +
    '<td style="padding:14px 0;border-bottom:1px solid ' + line + ';">' +
    '<a href="tel:' + tel + '" style="color:' + sky + ';font-size:17px;font-weight:800;text-decoration:none;">' + escapeHtml(r.phone) + '</a></td></tr>';

  rows += '<tr><td style="' + cell + '">📍 주소</td>' +
    '<td style="' + val + '">' + escapeHtml(r.address || "-") + '</td></tr>';

  rows += '<tr><td style="' + cell + '">문의 내용</td>' +
    '<td style="padding:14px 0;font-size:15px;line-height:1.6;color:' + ink + ';border-bottom:1px solid ' + line + ';">' + message + '</td></tr>';

  rows += '<tr><td style="' + cell + '">유입 페이지</td>' +
    '<td style="padding:14px 0;font-size:13.5px;color:#7C8A99;">' + escapeHtml(r.page || "-") + '</td></tr>';

  return '<!doctype html><html><body style="margin:0;padding:24px 12px;background:#F3F7FA;' +
    'font-family:-apple-system,BlinkMacSystemFont,Apple SD Gothic Neo,Malgun Gothic,sans-serif;">' +
    '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;margin:0 auto;' +
    'background:#ffffff;border-radius:18px;overflow:hidden;box-shadow:0 10px 30px rgba(14,53,80,.10);">' +
    '<tr><td style="background:' + sky + ';padding:30px 32px;">' +
    '<div style="color:#CDEEFB;font-size:13px;font-weight:700;letter-spacing:.5px;margin-bottom:6px;">레벨업과외 · 새 문의</div>' +
    '<div style="color:#ffffff;font-size:23px;font-weight:800;">📞 새 상담 신청이 도착했습니다</div></td></tr>' +
    '<tr><td style="padding:8px 32px 4px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0">' + rows + '</table></td></tr>' +
    '<tr><td style="padding:18px 32px 26px;">' +
    '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:' + soft + ';border-left:4px solid ' + sky + ';border-radius:10px;">' +
    '<tr><td style="padding:16px 18px;">' +
    '<div style="color:' + ink + ';font-size:14px;font-weight:700;margin-bottom:12px;">⏰ 빠른 연락이 상담 성사율을 높여요</div>' +
    '<a href="tel:' + tel + '" style="display:inline-block;background:' + sky + ';color:#ffffff;font-size:15px;font-weight:800;text-decoration:none;padding:11px 22px;border-radius:10px;">📞 전화 걸기</a>' +
    '</td></tr></table></td></tr>' +
    '<tr><td style="padding:16px 32px 26px;border-top:1px solid ' + line + ';text-align:center;">' +
    '<span style="color:#9AA8B5;font-size:12px;">level-up-lesson.com · 신청 시각: ' + escapeHtml(r.atDisplay) + '</span>' +
    '</td></tr></table></body></html>';
}

// 한글 HTML 메일이 안전하게 전달되도록 base64 인코딩한 MIME 메시지를 만듭니다.
function buildMime({ from, fromName, to, subject, html }) {
  const fromHeader = fromName ? encodeWord(fromName) + " <" + from + ">" : from;
  const b64body = btoa(String.fromCharCode(...new TextEncoder().encode(html)));
  const wrapped = (b64body.match(/.{1,76}/g) || [b64body]).join("\r\n");
  const headers = [
    "From: " + fromHeader,
    "To: " + to,
    "Subject: " + encodeWord(subject),
    "MIME-Version: 1.0",
    "Content-Type: text/html; charset=utf-8",
    "Content-Transfer-Encoding: base64",
  ];
  return headers.join("\r\n") + "\r\n\r\n" + wrapped + "\r\n";
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const path = url.pathname;

    if (request.method === "POST" && path === "/api/inquiry") {
      return handleInquiry(request, env);
    }
    if (path === "/favicon.ico") {
      return new Response(b64ToBytes(FAVICON_ICO), {
        headers: { "content-type": "image/x-icon", "cache-control": "public, max-age=604800" },
      });
    }
    if (path === "/apple-touch-icon.png") {
      return new Response(b64ToBytes(APPLE_ICON), {
        headers: { "content-type": "image/png", "cache-control": "public, max-age=604800" },
      });
    }
    if (path === "/" + INDEXNOW_KEY + ".txt") {
      return new Response(INDEXNOW_KEY, { headers: { "content-type": "text/plain; charset=utf-8" } });
    }
    if (path === "/robots.txt") {
      let body = "User-agent: GPTBot\nAllow: /\n\nUser-agent: OAI-SearchBot\nAllow: /\n\nUser-agent: ChatGPT-User\nAllow: /\n\nUser-agent: PerplexityBot\nAllow: /\n\nUser-agent: Perplexity-User\nAllow: /\n\nUser-agent: ClaudeBot\nAllow: /\n\nUser-agent: anthropic-ai\nAllow: /\n\nUser-agent: Claude-Web\nAllow: /\n\nUser-agent: Google-Extended\nAllow: /\n\nUser-agent: Applebot-Extended\nAllow: /\n\nUser-agent: Amazonbot\nAllow: /\n\nUser-agent: CCBot\nAllow: /\n\nUser-agent: Bytespider\nAllow: /\n\nUser-agent: Yeti\nAllow: /\n\nUser-agent: NaverBot\nAllow: /\n\nUser-agent: *\nAllow: /\n\nSitemap: https://level-up-lesson.com/sitemap.xml\n";
      if (env.DAUM_VERIFY) body += "\n" + env.DAUM_VERIFY + "\n"; // 다음 웹마스터도구 PIN 코드 줄
      return new Response(body, {
        headers: { "content-type": "text/plain; charset=utf-8", "cache-control": "public, max-age=86400" },
      });
    }
    const SM_CHUNK = 45000;
    if (path === "/sitemap.xml") {
      const total = seoLongTailPaths().length;
      const n = Math.ceil(total / SM_CHUNK);
      let body = '<?xml version="1.0" encoding="UTF-8"?>\n<sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n';
      // 인덱스와 개별 URL 이 같은 날짜를 써야 한다. 인덱스만 매일 갱신되면
      // "매일 바뀐다"고 알리면서 개별 URL 은 그대로여서 신호가 어긋난다.
      const smLm = DEPLOY_DATE;
      body += '<sitemap><loc>https://level-up-lesson.com/sitemap-core.xml</loc><lastmod>' + smLm + '</lastmod></sitemap>\n';
      for (let i = 1; i <= n; i++) body += '<sitemap><loc>https://level-up-lesson.com/sitemap-' + i + '.xml</loc><lastmod>' + smLm + '</lastmod></sitemap>\n';
      body += '</sitemapindex>\n';
      return new Response(body, {
        headers: { "content-type": "application/xml; charset=utf-8", "cache-control": "public, max-age=86400" },
      });
    }
    if (path === "/feed.xml" || path === "/rss.xml") {
      const HOST = "https://level-up-lesson.com";
      // 가치 높은 코어 페이지만 (가이드 우선 + 과목 허브 + 시도)
      const core = seoCoreSitemapPaths();
      const guides = core.filter((p) => p.indexOf("/guides") === 0);
      const hubs = core.filter((p) => p.split("-").length === 1 && p.indexOf("/guides") !== 0 && p !== "/regions");
      const sido = core.filter((p) => p.split("-").length === 2);
      const picked = guides.concat(hubs).concat(sido).slice(0, 300);
      // 최신 날짜순 정렬 (lastmod 기준)
      const items = picked.map((p) => ({ loc: HOST + p, lm: seoLastmod(p) }));
      items.sort((a, b) => (a.lm < b.lm ? 1 : -1));
      const now = new Date().toUTCString();
      let body = '<?xml version="1.0" encoding="UTF-8"?>\n<rss version="2.0"><channel>';
      body += '<title>레벨업과외 — 과목별 1:1 맞춤 과외</title>';
      body += '<link>' + HOST + '/</link>';
      body += '<description>과목별 전문 매칭, 23개 과목. 검정고시·코딩·논술·2022 개정 통합사회·통합과학까지.</description>';
      body += '<language>ko</language><lastBuildDate>' + now + '</lastBuildDate>';
      for (const it of items) {
        const d = new Date(it.lm + "T09:00:00+09:00").toUTCString();
        body += '<item><link>' + it.loc + '</link><guid>' + it.loc + '</guid><pubDate>' + d + '</pubDate></item>';
      }
      body += '</channel></rss>';
      return new Response(body, { headers: { "content-type": "application/rss+xml; charset=utf-8", "cache-control": "public, max-age=3600" } });
    }
    if (path === "/sitemap-core.xml") {
      const core = PAGE_PATHS.concat(seoCoreSitemapPaths()); // 홈·하위 페이지 + 코어 SEO 페이지
      let urls = "";
      for (const p of core) {
        const lm = seoLastmod(p);
        const loc = p === "/" ? "https://level-up-lesson.com/" : "https://level-up-lesson.com" + p;
        const pr = p === "/" ? "1.0" : "0.8";
        urls += '<url><loc>' + loc + '</loc><lastmod>' + lm + '</lastmod><changefreq>weekly</changefreq><priority>' + pr + '</priority></url>\n';
      }
      const body = '<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n' + urls + '</urlset>\n';
      return new Response(body, { headers: { "content-type": "application/xml; charset=utf-8", "cache-control": "public, max-age=86400" } });
    }
    if (path.startsWith("/sitemap-") && path.endsWith(".xml")) {
      const i = parseInt(path.slice(9, -4), 10);
      const all = seoLongTailPaths();
      if (!i || i < 1 || (i - 1) * SM_CHUNK >= all.length) {
        return new Response("Not Found", { status: 404 });
      }
      const slice = all.slice((i - 1) * SM_CHUNK, i * SM_CHUNK);
      let urls = "";
      for (const p of slice) {
        const lm = seoLastmod(p);
        const loc = p === "/" ? "https://level-up-lesson.com/" : "https://level-up-lesson.com" + p;
        const pr = p === "/" ? "1.0" : "0.7";
        urls += '<url><loc>' + loc + '</loc><lastmod>' + lm + '</lastmod><changefreq>monthly</changefreq><priority>' + pr + '</priority></url>\n';
      }
      const body = '<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n' + urls + '</urlset>\n';
      return new Response(body, {
        headers: { "content-type": "application/xml; charset=utf-8", "cache-control": "public, max-age=86400" },
      });
    }
    // 홈·하위 페이지 (site_pages.js). 끝에 슬래시가 붙은 주소는 정식 주소로 돌린다.
    {
      const p = path === "/index.html" ? "/" : path;
      if (p.length > 1 && p.endsWith("/") && PAGES[p.slice(0, -1)]) {
        return Response.redirect(url.origin + p.slice(0, -1) + url.search, 301);
      }
      const sitePage = renderSitePage(p, env);
      if (sitePage) {
        return new Response(sitePage, {
          headers: { "content-type": "text/html; charset=utf-8", "cache-control": p === "/" ? "no-cache" : "public, max-age=600" },
        });
      }
    }
    const seoPage = tryRenderSeoPage(path);
    if (seoPage) {
      return new Response(seoPage, {
        headers: { "content-type": "text/html; charset=utf-8", "cache-control": "public, max-age=3600" },
      });
    }
    return new Response("Not Found", { status: 404 });
  },

  // ───────── 매일 자동 색인 제출 (IndexNow: 네이버·빙·Yandex) ─────────
  // wrangler.toml 의 [triggers] crons 설정에 따라 하루 1회 실행됩니다.
  // 전체 URL을 매일 BATCH 개씩 순환 제출하여 며칠에 걸쳐 전 페이지를 알립니다.
  async scheduled(event, env, ctx) {
    const HOST = "level-up-lesson.com";
    const BATCH = 1000;
    const all = ["/"].concat(seoSitemapPaths());
    const day = Math.floor(Date.now() / 86400000);
    const start = (day * BATCH) % all.length;
    let slice = all.slice(start, start + BATCH);
    if (slice.length < BATCH) slice = slice.concat(all.slice(0, BATCH - slice.length));
    const urlList = slice.map((p) => (p === "/" ? "https://" + HOST + "/" : "https://" + HOST + p));
    const body = JSON.stringify({
      host: HOST,
      key: INDEXNOW_KEY,
      keyLocation: "https://" + HOST + "/" + INDEXNOW_KEY + ".txt",
      urlList: urlList,
    });
    const endpoints = ["https://api.indexnow.org/indexnow", "https://searchadvisor.naver.com/indexnow"];
    for (const ep of endpoints) {
      try {
        const r = await fetch(ep, {
          method: "POST",
          headers: { "content-type": "application/json; charset=utf-8" },
          body: body,
        });
        console.log("IndexNow 제출:", ep, "상태", r.status, "URL", urlList.length + "개", "시작 인덱스", start);
      } catch (e) {
        console.log("IndexNow 실패:", ep, e && e.message ? e.message : e);
      }
    }
  },
};
